(()=>{'use strict';const url='https://dxpzqepbkkhcbpqmnokn.supabase.co',key='sb_publishable_rilP1z9ZWO70OtP_2t0fdQ_2CEvpobE',storage='sb-dxpzqepbkkhcbpqmnokn-auth-token';let session=null,plans=[],selected=['start','pro','firma'].includes(new URLSearchParams(location.search).get('plan'))?new URLSearchParams(location.search).get('plan'):'pro',membership=null;const $=id=>document.getElementById(id);const money=n=>new Intl.NumberFormat('cs-CZ').format(n/100)+' Kč';function render(){const annual=$('interval').value==='annual';$('billing-plans').replaceChildren(...plans.map(p=>{const card=document.createElement('article');card.className='card plan';const h=document.createElement('h3');h.textContent=p.name;const price=document.createElement('div');price.className='price';price.textContent=money(annual?p.annual_cents:p.monthly_cents);const note=document.createElement('small');note.textContent=annual?' / rok':' / měsíc';price.append(note);const desc=document.createElement('p');desc.textContent=p.description||'Zakázky, kalendář a finance na jednom místě.';const b=document.createElement('button');b.className='btn light';b.type='button';b.setAttribute('aria-pressed',String(selected===p.code));b.textContent=selected===p.code?'Vybraný plán':'Vybrat '+p.name;b.addEventListener('click',()=>{selected=p.code;render()});card.append(h,price,desc,b);return card}))}async function request(path){const r=await fetch(url+path,{headers:{apikey:key,...(session?{Authorization:'Bearer '+session.access_token}:{})}});if(!r.ok)throw Error('Údaje se nepodařilo načíst.');return r.json()}async function currentSubscription(){const org=$('organization').value;if(!org)return;membership=org;const subs=await request('/rest/v1/subscriptions?select=plan_code,status,is_comped,provider,provider_customer_id&organization_id=eq.'+encodeURIComponent(org));const sub=subs[0];$('subscription').textContent=sub?'Současný tarif: '+sub.plan_code+' · stav: '+sub.status+(sub.is_comped?' · účet bez poplatku':''):'';$('portal').classList.toggle('hide',!(sub?.provider==='stripe'&&sub?.provider_customer_id));$('checkout').disabled=!!sub?.is_comped}async function init(){try{plans=await request('/rest/v1/plan_catalog?select=code,name,description,monthly_cents,annual_cents&active=eq.true&is_public=eq.true&order=sort_order');render();try{session=JSON.parse(localStorage.getItem(storage)||'null')}catch{}if(session?.refresh_token&&(!session.access_token||session.expires_at*1000<Date.now()+60000)){const r=await fetch(url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!r.ok)session=null;else{session=await r.json();localStorage.setItem(storage,JSON.stringify(session))}}if(!session?.access_token){$('billing-auth').innerHTML='Pro správu tarifu se <a href="/app">přihlaste</a> nebo si <a href="/app?mode=register">vytvořte účet</a>.';return}const r=await fetch(url+'/auth/v1/user',{headers:{apikey:key,Authorization:'Bearer '+session.access_token}});if(!r.ok)throw Error('Přihlášení vypršelo. Přihlaste se znovu v aplikaci.');const user=await r.json();const memberships=await request('/rest/v1/organization_memberships?select=organization_id,role,organizations(name)&user_id=eq.'+encodeURIComponent(user.id));const editable=memberships.filter(m=>['owner','admin'].includes(m.role));$('billing-auth').textContent='Přihlášeno: '+user.email;if(!editable.length){$('billing-status').textContent='Tarif může spravovat vlastník nebo administrátor organizace.';return}$('organization').replaceChildren(...editable.map(m=>{const o=document.createElement('option');o.value=m.organization_id;o.textContent=m.organizations?.name||'Moje organizace';return o}));$('org-control').classList.remove('hide');await currentSubscription()}catch(error){$('billing-auth').textContent=error.message;$('billing-status').className='status error'}}async function checkout(action){const status=$('billing-status');status.className='status';status.textContent='Ověřuji dostupnost plateb…';$('checkout').disabled=true;$('portal').disabled=true;try{if(!session||!membership)throw Error('Nejdříve se přihlaste do aplikace.');const res=await fetch('/supabase/functions/v1/create-checkout',{method:'POST',headers:{apikey:key,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({action,organization_id:membership,plan_code:selected,interval:$('interval').value})});const data=await res.json();if(!res.ok)throw Error(data.error||'Platební služba není dostupná.');const destination=new URL(data.url);if(destination.protocol!=='https:'||!['checkout.stripe.com','billing.stripe.com'].includes(destination.hostname))throw Error('Platební služba vrátila neplatný odkaz.');location.assign(destination.href)}catch(error){status.className='status error';status.textContent=error.message}finally{$('checkout').disabled=false;$('portal').disabled=false}}$('interval').addEventListener('change',render);$('organization').addEventListener('change',()=>currentSubscription().catch(e=>{$('billing-status').textContent=e.message}));$('checkout').addEventListener('click',()=>checkout('checkout'));$('portal').addEventListener('click',()=>checkout('portal'));if(new URLSearchParams(location.search).has('success'))$('billing-status').textContent='Návrat z platební služby. Aktuální stav předplatného načítáme z databáze.';if(new URLSearchParams(location.search).has('cancelled'))$('billing-status').textContent='Platba byla přerušena. Tarif se tím nezměnil.';init()})();
